"""Parser for 23andMe raw genotype export files.

Format reference (from real sample files; the rows here are invented):

    # This data file generated by 23andMe at: Mon Jun 01 00:00:00 2020
    #
    # This file contains raw genotype data ...
    #
    # rsid  chromosome  position  genotype
    rs3999990021	1	3999021	AA
    rs3999990022	1	3999022	AG
    i3999023	5	3999023	CT
    rs3999990001	1	3999001	--

Specifics:
    - Comment lines start with `#`.
    - Tab-delimited, 4 columns of data.
    - Genotype is concatenated in one column (e.g., "AG" not "A<tab>G").
    - Haploid calls on X/Y/MT appear as single characters (e.g., "A").
    - No-calls represented as `--`.
    - Contains I-prefixed internal probe IDs (i3000043, i5006212)
      alongside rs-numbers. These are passed through as-is.
    - Build 37 (older) or Build 38 (newer); check header comments.
    - Detection key: canonical banner ``# This data file generated by 23andMe``
      (or the v5 ``is generated by`` form). Current v5 exports open with
      ``# file_id:``, ``# signature:`` and ``# timestamp:`` lines and a bare
      ``#``, so the banner is on line 5; it may follow any comment lines.
      A bare "23andMe" substring in a comment is NOT sufficient — it would
      false-positive on transcoded fixtures and third-party tool output.
"""

from __future__ import annotations

import logging
from typing import TYPE_CHECKING, ClassVar

from allelix.models import DEFAULT_BUILD, Variant
from allelix.parsers._helpers import (
    DamagedFileError,
    is_haploid_call,
    open_genotype_text,
    split_csv_line,
    split_genotype,
)
from allelix.parsers.base import GenotypeMetadata, GenotypeParser, header_build_label

if TYPE_CHECKING:
    from collections.abc import Iterator
    from pathlib import Path

logger = logging.getLogger(__name__)

# Known canonical banner variants 23andMe wraps raw exports in.
# The original v2/v3/v4-era exports used the verbatim ``generated by`` form;
# the June 2026 v5 export prose was edited to ``is generated by`` (with a
# trailing period in some samples). Match either; future vendor banner
# edits get a new entry here.
#
# Why a tuple of exact prefixes instead of a loose ``"23andMe" in line``
# substring match: a bare substring check false-positives on transcoded
# fixtures and third-party tool output. Files that strip the canonical
# banner entirely (WGSExtract output, Genetic Lifehacks converter output,
# privacy-conscious users who delete the comment block) are out of scope
# for this parser by design, and no other parser reads them: Allelix cannot
# tell which strand a file of unidentified source is on, so it rejects it
# rather than guess (owner decision, 2026-10-17).
_CANONICAL_PREFIXES: tuple[str, ...] = (
    "# This data file generated by 23andMe",
    "# This data file is generated by 23andMe",
)
SNIFF_LINE_LIMIT = 50
EXPECTED_COLUMNS = 4


class TwentyThreeAndMeParser(GenotypeParser):
    """Parser for 23andMe consumer DNA genotype files."""

    name: ClassVar[str] = "23andme"
    display_name: ClassVar[str] = "23andMe"
    file_extensions: ClassVar[list[str]] = [".txt"]
    url: ClassVar[str] = "https://www.23andme.com"

    def can_parse(self, file_path: Path) -> bool:
        """Recognize a real 23andMe export by its canonical banner line.

        Real exports carry one of the variants in ``_CANONICAL_PREFIXES``:
        the historical ``# This data file generated by 23andMe at: ...`` form
        or the June 2026 v5 ``# This data file is generated by 23andMe.`` form.
        The banner need not be the first line: current v5 exports put
        ``# file_id:``, ``# signature:``, ``# timestamp:`` and a bare ``#``
        before it, and some files have user-prepended comments. The scan
        loop reads up to ``SNIFF_LINE_LIMIT`` comment or blank lines. A bare
        "23andMe" substring mention without one of the canonical prefixes is
        rejected (see ``_CANONICAL_PREFIXES`` rationale).
        """
        try:
            with open_genotype_text(file_path) as fh:
                for _ in range(SNIFF_LINE_LIMIT):
                    line = fh.readline()
                    if not line:
                        return False
                    if not line.strip():
                        continue
                    # A spreadsheet's CSV save quotes a comment that holds a comma.
                    line = line.removeprefix('"')
                    if not line.startswith("#"):
                        return False
                    if any(line.startswith(p) for p in _CANONICAL_PREFIXES):
                        return True
        except (OSError, UnicodeDecodeError, DamagedFileError):
            return False
        return False

    def parse(self, file_path: Path) -> Iterator[Variant]:
        """Stream Variant objects, skipping comments and malformed lines."""
        with open_genotype_text(file_path) as fh:
            for lineno, raw in enumerate(fh, start=1):
                line = raw.rstrip("\r\n")
                # A spreadsheet's CSV save quotes a comment that holds a comma.
                if not line or line.startswith(("#", '"#')):
                    continue

                # A row re-saved with spaces instead of tabs (a text editor or
                # spreadsheet round trip) is split on runs of whitespace; rsIDs,
                # chromosomes, positions and genotypes hold none. A row a
                # spreadsheet saved as CSV is split on commas, its quotes and
                # padding beyond the four columns dropped (an empty genotype
                # stays a no-call).
                if "\t" in line:
                    parts = line.split("\t")
                elif "," in line:
                    parts = split_csv_line(line, EXPECTED_COLUMNS)
                else:
                    parts = line.split()
                if len(parts) != EXPECTED_COLUMNS:
                    logger.warning(
                        "Line %d: expected %d columns, got %d — skipping",
                        lineno,
                        EXPECTED_COLUMNS,
                        len(parts),
                    )
                    continue

                rsid, chrom, pos_str, genotype = parts
                try:
                    position = int(pos_str)
                except ValueError:
                    logger.warning("Line %d: invalid position %r — skipping", lineno, pos_str)
                    continue

                allele1, allele2 = split_genotype(genotype)

                yield Variant(
                    rsid=rsid,
                    chromosome=chrom,
                    position=position,
                    allele1=allele1,
                    allele2=allele2,
                    build=DEFAULT_BUILD,
                    haploid=is_haploid_call(genotype),
                )

    def get_metadata(self, file_path: Path) -> GenotypeMetadata:
        """Extract the header's build line. 23andMe files have no sample ID field.

        A comment line a spreadsheet quoted (``"# ..., build 37",,,``) is read
        as the comment it holds, so it neither stops the header scan nor
        hides a build stated on it.
        """
        try:
            with open_genotype_text(file_path, errors="replace") as fh:
                build = header_build_label(_unquoted_comment(raw) for raw in fh)
        except (OSError, DamagedFileError):
            build = None
        return GenotypeMetadata(format=self.name, sample_id="", build=build)


def _unquoted_comment(raw: str) -> str:
    """``raw`` with a spreadsheet's CSV quoting of a ``#`` comment removed."""
    line = raw.rstrip("\r\n").lstrip("\ufeff")
    if not line.startswith('"#'):
        return raw
    line = line[1:].rstrip(",")
    return line.removesuffix('"').replace('""', '"')
